int licznik = 0;
int liczba = 0;

int minimum, maksimum, jasnosc, wilgotnosc, temperatura;

void Znak(int iNumer) {

  switch (iNumer) {

    case 0: PORTD = (PORTD & 0b00000011) | 0b00000000; PORTB |= 0b00000001; break;

    case 1: PORTD = (PORTD & 0b00000011) | 0b01111100; PORTB |= 0b00000001; break;

    case 2: PORTD = (PORTD & 0b00000011) | 0b10010000; PORTB &= 0b11111110; break;

    case 3: PORTD = (PORTD & 0b00000011) | 0b11000000; PORTB &= 0b11111110; break;

    case 4: PORTD = (PORTD & 0b00000011) | 0b01100100; PORTB &= 0b11111110; break;

    case 5: PORTD = (PORTD & 0b00000011) | 0b01101000; PORTB &= 0b11111110; break;

    case 6: PORTD = (PORTD & 0b00000011) | 0b00001000; PORTB &= 0b11111110; break;

    case 7: PORTD = (PORTD & 0b00000011) | 0b11100000; PORTB |= 0b00000001; break;

    case 8: PORTD = (PORTD & 0b00000011) | 0b00000000; PORTB &= 0b11111110; break;

    case 9: PORTD = (PORTD & 0b00000011) | 0b01000000; PORTB &= 0b11111110; break;

    default:
      PORTD = (PORTD & 0b00000011) | 0b11011000;
      PORTB &= 0b11111110;
      break;
  }
}

void setup() {
  // D2-D7 jako wyjścia
  DDRD |= 0b11111100;

  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);

  delay(1000);

  minimum = analogRead(A0);
  maksimum = minimum;
}

void loop() {
  digitalWrite(11, LOW);

  Znak(liczba % 10);
  digitalWrite(10, HIGH);
  delay(2);

  digitalWrite(10, LOW);

  Znak((liczba / 10) % 10);
  digitalWrite(11, HIGH);
  delay(2);

  if (licznik++ > 100) {
    jasnosc = analogRead(A0);

    if (minimum > jasnosc) {
      minimum = jasnosc;
    }

    if (maksimum < jasnosc) {
      maksimum = jasnosc;
    }

    if (minimum != maksimum) {
      jasnosc = 99 * (jasnosc - minimum) / (maksimum - minimum);
    }

    liczba = jasnosc;
    licznik = 0;
  }
}
